def cachedproperty_new(func):
    class CachedProperty:
        def __init__(self, func):
            self.func = func
        def __get__(self, obj, objtype=None):
            if obj is None:
                return self
            return setattr(obj, self.func.__name__, self.func(obj)) or getattr(obj, self.func.__name__)
    return CachedProperty(func)

class A:
    foo = cachedproperty_new(lambda self: (print("Calculating..."), 42)[1])

a = A()
print(f"First call: {a.foo}")
print(f"Second call: {a.foo}")
